-- One slot. Draft only.
BEGIN;
-- PT105-S2-Q15
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND q.stimulus=$batch01$A report of a government survey concluded that Center City was among the ten cities in the nation with the highest dropout rate from its schools. The survey data were obtained by asking all city residents over the age of 19 whether they were high school graduates and computing the proportion who were not. A city school of official objected that the result did not seem accurate according to the schools’ figures.$batch01$ AND q.prompt=$batch01$The school official can most properly criticize the reasoning by which the survey report reached its result for failure to do which one of the following?$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT105-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$take into account instances of respondents’ dropping out that occurred before the respondents reached high school$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S2-Q15 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$ask residents whether they had completed their high school work in fewer than the usual number of years$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S2-Q15 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$distinguish between residents who had attended the city’s schools and those who had received their schooling elsewhere$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S2-Q15 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$predict the effect of the information contained in the report on future high school dropout rates for the city$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S2-Q15 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$consider whether a diploma from the city’s high schools signaled the same level of achievement over time$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S2-Q15 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT105-S2-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion of the survey report$batch01$, $batch01$Center City has one of the nation's ten highest dropout rates *from its schools*.$batch01$), (1, $batch01$Method$batch01$, $batch01$Ask all current city residents over 19 whether they graduated from high school and count those who did not.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$A resident's schooling may have happened in another city. If many adult residents moved into Center City after dropping out elsewhere, their answers raise the measured share of nongraduates without saying anything about Center City's schools. Conversely, former students who left the city disappear from the sample. The measured population and the claimed school population are different.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the missing distinction between current residents and people who attended the city's schools.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The survey asks whether respondents graduated from high school, so dropping out before reaching high school may sound like a counting issue. But such a respondent would still be a nongraduate. The central problem is whose schools the nongraduation reflects. Someone who left school before high school in another city is still no evidence about Center City's schools.$batch01$), ($batch01$B$batch01$, $batch01$Finishing high school early still makes one a graduate. The survey already asks whether the person graduated, not how long it took.$batch01$), ($batch01$C$batch01$, $batch01$The survey counts Center City residents without separating those educated in Center City from those educated elsewhere. A dropout in another city's schools cannot establish a dropout from Center City's schools. The report labels its sample as if it measured the target.$batch01$), ($batch01$D$batch01$, $batch01$The report makes a claim about current or past dropout rates; predicting how publicity affects future rates would not validate that claim.$batch01$), ($batch01$E$batch01$, $batch01$Changing diploma standards could affect what graduation means, but the first defect is that many surveyed residents may have no connection to the schools whose dropout rate the report claims to measure.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT105-S2-Q15$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
